template <typename T1, typename T2>
struct CommonTypeConcept {
    // Requires std::declval to simulate operation result
    // The ternary operator forces compile-time type promotion rules
    using type = decltype(
        true ? std::declval<T1>() : std::declval<T2>()
    );
};

// Standard Usage (Alias Template C++14)
template <typename... T>
using common_type_t = typename std::common_type<T...>::type;

using R1 = common_type_t<int, float>;    // float
using R2 = common_type_t<const long&, int>; // long

// Recursive definition needed for > 2 types
// common_type<T1, T2, T3> == common_type<common_type<T1, T2>, T3>

using R3 = common_type_t<char, short, double>; // double
